; =====================================================================
;  STATUS.ASM -- the status bar's look (T-GFX-3, D54)
;
;  The two status lines are ANTIC mode 4 in their own font (STFONT,
;  generated by tools/mkstat.py): white 3 x 7 letters, a coin for gold
;  and a person for population, and each player's numbers in that
;  player's cursor colour.  Mode 4 shows COLBK behind the text, so a
;  DLI on the blank line above sets line 1's background and one on
;  line 1 sets line 2's; the border above stays black.
; =====================================================================

C_SGOLD =  $2C          ; COLPF0: the coin, the people's heads
C_SRED  =  $48          ; COLPF1: player 1 (C_CUR0, a step brighter)
C_SWHT  =  $0C          ; COLPF2: text
C_STURQ =  $AC          ; COLPF3: player 2 (C_CUR1), inverse characters
C_SBK1  =  $84          ; line 1 background
C_SBK2  =  $80          ; line 2 background, a shade darker

; ---------------------------------------------------------------------
;  ST_COLS -- the status bar's font and colours into the OS shadows
;  (DISP_INIT, GAME_START).  Trashes A.
; ---------------------------------------------------------------------
ST_COLS
        LDA #C_SGOLD
        STA COLOR0
        LDA #C_SRED
        STA COLOR1
        LDA #C_SWHT
        STA COLOR2
        LDA #C_STURQ
        STA COLOR3
        LDA #C_SBRD     ; black above the bar
        STA COLOR4
        LDA #>STFONT
        STA CHBAS
        RTS

; ---------------------------------------------------------------------
;  ST_VBI -- each frame (VBI_D): the two backgrounds with attract mode
;  applied, and VDSLST back at the first DLI.  Trashes A.
; ---------------------------------------------------------------------
ST_VBI
        LDA #C_SBK1
        EOR COLRSH
        AND DRKMSK
        STA STBK
        LDA #C_SBK2
        EOR COLRSH
        AND DRKMSK
        STA STBK+1
        LDA #<DLI_ST
        STA VDSLST
        LDA #>DLI_ST
        STA VDSLST+1
        RTS

; ---------------------------------------------------------------------
;  DLI_ST  -- last blank line: status line 1's background
;  DLI_ST2 -- end of status line 1: line 2's background
;  Each points VDSLST at the next DLI.  Keep all registers.
; ---------------------------------------------------------------------
DLI_ST
        PHA
        LDA STBK
        STA WSYNC
        STA COLBK
        LDA #<DLI_ST2
        STA VDSLST
        LDA #>DLI_ST2
        STA VDSLST+1
        PLA
        RTI

DLI_ST2
        PHA
        LDA STBK+1
        STA WSYNC
        STA COLBK
        LDA #<DLI_MAP
        STA VDSLST
        LDA #>DLI_MAP
        STA VDSLST+1
        PLA
        RTI

; ---------------------------------------------------------------------
;  ST_DEC -- TXT_DEC in a colour, then white again
;  In: as TXT_DEC, and Y = colour (TX_RED, TX_TURQ).
;  Trashes A, X, Y, as TXT_DEC.
; ---------------------------------------------------------------------
ST_DEC
        STY TXCOL
        JSR TXT_DEC
        LDA #0
        STA TXCOL
        RTS
